INSERT INTO public."Estimulo" (id,text,"criteriosAvaliacao",feedback,"order","skillCategoryId","difficultyLevelId","deletedAt","deletedBy",status,"updatedAt","createdBy",habilitado) VALUES
	 ('c6149e05-e32a-4cae-88c6-b5bb37561c77','(Com raiva) Meu médico disse que eu tenho que te procurar por causa do meu “problema com raiva”. Às vezes, quando fico muito irritado, perco o controle e agrido as pessoas. Fico com muita raiva quando dizem coisas idiotas! Você tem certeza de que consegue me ajudar com isso?','Critérios de avaliação:
- Validar a experiência do paciente 
- Aumentar a consciência emocional do paciente
-  Realizar estruturação colaborativa da sessão 
- Introduzir a ideia de regulação emocional
- Avaliação de percepção do problema
- Estabelecer expectativas adequadas sobre a natureza e o impacto da TCC.','Forneça um feedback que considere os critérios de avaliação mas permita flexibilidade de acordo com o estilo do terapeuta. Forneça um percentual de adequação, só considerar a resposta adequada quando cumpriu todos os critérios acima.',3,'dbc4f700-7054-4ade-aaeb-f30ea5ede426','56a12911-d096-4ec3-ab55-a9e4f645517b',NULL,NULL,'active',NULL,NULL,true),
	 ('893827b8-f437-45e5-9234-39456d171236','(Preocupado) Eu realmente preciso entender por que sou do jeito que sou hoje. Acho que compreender meu passado e minha infância é muito importante, mas parece que essa abordagem não trabalha com isso, não é?','Critérios de avaliação:
- Validar a experiência do paciente.
- Explicar a lógica de como a TCC funciona
- Promover esperança quanto ao uso eficaz da TCC.
- Checagem de compreensão','Forneça um feedback que considere os critérios de avaliação mas permita flexibilidade de acordo com o estilo do terapeuta. Forneça um percentual de adequação, só considerar a resposta adequada quando cumpriu todos os critérios acima.',4,'dbc4f700-7054-4ade-aaeb-f30ea5ede426','56a12911-d096-4ec3-ab55-a9e4f645517b',NULL,NULL,'active',NULL,NULL,true),
	 ('80e307c5-9349-4650-8bdd-a19948a7ef52','(Curioso) Como a terapia funciona?','Critérios de avaliação:
- Validar a experiência do paciente.
- Explicar a lógica de como a TCC pode ser utilizada para abordar as preocupações.
- Promover esperança quanto ao uso eficaz da TCC.
